"""``cameras`` table. ``geom`` is generated by PostGIS from ``lat``/``lon`` (query it in SQL)."""

from datetime import datetime
from typing import Any

from sqlalchemy import Boolean, CheckConstraint, DateTime, Double, String, func, text
from sqlalchemy.dialects.postgresql import JSONB
from sqlalchemy.orm import Mapped, mapped_column

from nadjet_api.db import Base

STATUS_VALUES = "('unknown','online','degraded','offline')"


class Camera(Base):
    __tablename__ = "cameras"
    __table_args__ = (
        CheckConstraint(f"status IN {STATUS_VALUES}", name="cameras_status_valid"),
        CheckConstraint("heading_deg >= 0 AND heading_deg < 360", name="cameras_heading_valid"),
    )

    id: Mapped[str] = mapped_column(String(63), primary_key=True)
    name: Mapped[str] = mapped_column(String(255))
    stream_path: Mapped[str] = mapped_column(String(63))
    lat: Mapped[float] = mapped_column(Double)
    lon: Mapped[float] = mapped_column(Double)
    road: Mapped[str] = mapped_column(String(64))
    pk_km: Mapped[float | None] = mapped_column(Double, default=None)
    heading_deg: Mapped[float] = mapped_column(Double, default=0)
    wilaya: Mapped[str] = mapped_column(String(64))
    zones: Mapped[dict[str, Any] | None] = mapped_column(JSONB, default=None)
    status: Mapped[str] = mapped_column(String(16), server_default=text("'unknown'"))
    simulated: Mapped[bool] = mapped_column(Boolean, server_default=text("true"))
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), server_default=func.now())
    updated_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), server_default=func.now())
